1	import { createBrowserRouter, Navigate, RouterProvider } from 'react-router-dom';
2	import { useAuth } from '@/lib/auth';
3	import { AppShell } from '@/components/layout/app-shell';
4	import { LoginPage } from '@/pages/login';
5	import { AuthCallbackPage } from '@/pages/auth-callback';
6	import { NewTradePage } from '@/pages/new-trade';
7	import { TradeDetailPage } from '@/pages/trade-detail';
8	import { TradesPage } from '@/pages/trades';
9	import { DashboardPage } from '@/pages/dashboard';
10	import { CoachPage } from '@/pages/coach';
11	import { CoachSetupPage } from '@/pages/coach-setup';
12	import { BrokerSettingsPage } from '@/pages/settings-broker';
13	import { PropShieldPage } from '@/pages/prop-shield';
14	import { PropShieldNewPage } from '@/pages/prop-shield-new';
15	import { PropShieldDetailPage } from '@/pages/prop-shield-detail';
16	import { BillingSettingsPage } from '@/pages/settings-billing';
17	
18	// ============================================================
19	// Protected layout — redirects to /login if not authenticated
20	// ============================================================
21	
22	function ProtectedLayout() {
23	  const { token, isLoading } = useAuth();
24	
25	  if (isLoading) {
26	    return (
27	      <div className="flex min-h-screen items-center justify-center">
28	        <p className="text-muted-foreground">Loading…</p>
29	      </div>
30	    );
31	  }
32	
33	  if (!token) {
34	    return <Navigate to="/login" replace />;
35	  }
36	
37	  return <AppShell />;
38	}
39	
40	// ============================================================
41	// Router
42	// ============================================================
43	
44	const router = createBrowserRouter([
45	  {
46	    path: '/login',
47	    element: <LoginPage />,
48	  },
49	  {
50	    path: '/auth/callback',
51	    element: <AuthCallbackPage />,
52	  },
53	  {
54	    element: <ProtectedLayout />,
55	    children: [
56	      {
57	        index: true,
58	        element: <Navigate to="/dashboard" replace />,
59	      },
60	      {
61	        path: '/dashboard',
62	        element: <DashboardPage />,
63	      },
64	      {
65	        path: '/trades',
66	        element: <TradesPage />,
67	      },
68	      {
69	        path: '/trades/new',
70	        element: <NewTradePage />,
71	      },
72	      {
73	        path: '/trades/:id',
74	        element: <TradeDetailPage />,
75	      },
76	      {
77	        path: '/coach',
78	        element: <CoachPage />,
79	      },
80	      {
81	        path: '/coach/setup',
82	        element: <CoachSetupPage />,
83	      },
84	      {
85	        path: '/prop-shield',
86	        element: <PropShieldPage />,
87	      },
88	      {
89	        path: '/prop-shield/new',
90	        element: <PropShieldNewPage />,
91	      },
92	      {
93	        path: '/prop-shield/:id',
94	        element: <PropShieldDetailPage />,
95	      },
96	      {
97	        path: '/settings',
98	        element: <Navigate to="/settings/broker" replace />,
99	      },
100	      {
101	        path: '/settings/broker',
102	        element: <BrokerSettingsPage />,
103	      },
104	      {
105	        path: '/settings/billing',
106	        element: <BillingSettingsPage />,
107	      },
108	    ],
109	  },
110	]);
111	
112	export function App() {
113	  return <RouterProvider router={router} />;
114	}
