1	import { Link } from 'react-router-dom';
2	import { Button } from '@/components/ui/button';
3	import { SummaryCards } from '@/components/analytics/summary-cards';
4	import { BreakdownTable } from '@/components/analytics/breakdown-table';
5	import { DayOfWeekChart } from '@/components/analytics/day-of-week-chart';
6	import { MistakeChart } from '@/components/analytics/mistake-chart';
7	import { RDistribution } from '@/components/analytics/r-distribution';
8	import { useBySetup, useBySession, useByInstrument, useSummary } from '@/hooks/use-analytics';
9	import { SETUP_TYPE_LABELS, SESSION_LABELS } from '@/lib/constants';
10	
11	export function DashboardPage() {
12	  const summary = useSummary();
13	  const bySetup = useBySetup();
14	  const bySession = useBySession();
15	  const byInstrument = useByInstrument();
16	
17	  const hasNoTrades =
18	    !summary.isLoading && summary.data != null && summary.data.total_trades === 0;
19	
20	  if (hasNoTrades) {
21	    return (
22	      <div className="flex flex-col items-center justify-center gap-4 py-24">
23	        <h1 className="text-2xl font-semibold">Dashboard</h1>
24	        <p className="max-w-sm text-center text-muted-foreground">
25	          Start journaling to see your analytics
26	        </p>
27	        <Button asChild>
28	          <Link to="/trades/new">Log Your First Trade</Link>
29	        </Button>
30	      </div>
31	    );
32	  }
33	
34	  return (
35	    <div className="space-y-6">
36	      <h1 className="text-2xl font-semibold">Dashboard</h1>
37	
38	      <SummaryCards />
39	
40	      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
41	        <BreakdownTable
42	          title="By Setup Type"
43	          rows={bySetup.data ?? []}
44	          labelMap={SETUP_TYPE_LABELS as Record<string, string>}
45	        />
46	        <BreakdownTable
47	          title="By Session"
48	          rows={bySession.data ?? []}
49	          labelMap={SESSION_LABELS as Record<string, string>}
50	        />
51	        <BreakdownTable title="By Instrument" rows={byInstrument.data ?? []} />
52	        <DayOfWeekChart />
53	        <MistakeChart />
54	        <RDistribution />
55	      </div>
56	    </div>
57	  );
58	}
